package com.eurobuddha.terminalide.terminal;

import com.eurobuddha.minimacore.i18n.Language;
import static com.eurobuddha.minimacore.i18n.R.string.*;

/** Explicit Terminal IDE warnings and local failures only. Never use for user content, names, addresses or filenames.
 * Reuses Parlons SystemMessages' fixed lookup, literal captures and bounded diagnostic recursion.
 * Generated by adapt-pandamonium-wallet-error-languages.py from localization/terminal-messages.json. */
public final class TerminalMessages {
    private TerminalMessages() {}
    public static CharSequence error(Throwable error) {
        if (error == null) return Language.msg(l10n_wallet_operation_failed);
        return message(error.getMessage() == null ? error.toString() : error.getMessage());
    }
    public static CharSequence message(String value) { return message(value,0); }
    private static CharSequence message(String value,int depth) {
        if (value == null) return "";
        if (depth >= 8) return value;
        switch(value) {
            case "Unbounded 'coins' on a busy address can build a giant reply that crashes the node AND this app (Binder ~1MB limit is uncatchable). Add depth: (start small, e.g. depth:4) or relevant:true.": return Language.msg(l10n_terminal_ide_coins_warning);
            case "'history' returns FULL txpow bodies (~14KB each; default max ~100) and can exceed the IPC limits — big replies crash the node/app. Use max:8 or less and page with offset:.": return Language.msg(l10n_terminal_ide_history_warning);
            case "'printtree' without depth: can return a huge tree. Add depth: (e.g. depth:10).": return Language.msg(l10n_terminal_ide_tree_warning);
            case "could not open the chosen file": return Language.msg(l10n_terminal_ide_file_open);
            case "cannot create the export folder": return Language.msg(l10n_terminal_ide_export_folder);
            case "The embedded node did not respond. Check its status in Minima Core.": return Language.msg(l10n_terminal_ide_timeout);
            default: break;
        }
        for(int i=0;i<PATTERNS.length;i++) {
            java.util.regex.Matcher match=PATTERNS[i].matcher(value);
            if(!match.matches())continue;
            Object[] arguments=new Object[match.groupCount()];
            for(int j=0;j<arguments.length;j++) {
                String literal=match.group(j+1);
                arguments[j]=DIAGNOSTIC[i][j] ? message(literal,depth+1) : literal;
            }
            return Language.msg(RESOURCES[i],arguments);
        }
        return value;
    }
    private static final java.util.regex.Pattern[] PATTERNS={

    };
    private static final int[] RESOURCES={};
    private static final boolean[][] DIAGNOSTIC={};
}
